    'Pass အတွင်းရှိ ကီးများ မပြောင်းပါ၊ ထို့ကြောင့် တစ်စုံတစ်ယောက် ယခင်က သိမ်းထားသော Pass မိတ္တူကို စကားဝှက်ဟောင်းဖြင့် ဖွင့်နိုင်ဆဲ ဖြစ်သည်။',
  'Make a new key': 'ကီး အသစ် ပြုလုပ်ရန်',
  'A new key stops the old one from opening Pass here.':
    'ကီးအသစ်သည် ကီးဟောင်းဖြင့် ဤနေရာတွင် Pass ဖွင့်ခြင်းကို တားဆီးသည်။',
  'New recovery key': 'ပြန်ယူကီး အသစ်',
  'The old key still opens a copy of Pass somebody kept from before.':
    'တစ်စုံတစ်ယောက် ယခင်က သိမ်းထားသော Pass မိတ္တူကို ကီးဟောင်းဖြင့် ဖွင့်နိုင်ဆဲ ဖြစ်သည်။',
  'Set up Pass': 'Pass စနစ်ထည့်ရန်',
  'Your Pass password encrypts everything in Pass. Nobody can reset it for you.':
    'သင့် Pass စကားဝှက်သည် Pass ထဲရှိ အရာအားလုံးကို ကုဒ်ဝှက်သည်။ မည်သူမျှ သင့်အတွက် ပြန်သတ်မှတ်ပေး၍ မရပါ။',
  'Setting up…': 'စနစ်ထည့်နေသည်…',
  'Pass could not be set up.': 'Pass ကို စနစ်ထည့်၍ မရပါ။',
  'Invitation sent to {email}': '{email} သို့ ဖိတ်ကြားချက် ပို့ပြီး',
